import{_ as n,o as t,c as i,a3 as r}from"./chunks/framework.B9qR_F1m.js";const a="/bilder/uebersicht.jpg",c=JSON.parse('{"title":"Übersicht","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/uebersicht.md","filePath":"bereiche/uebersicht.md"}'),s={name:"bereiche/uebersicht.md"};function l(d,e,o,g,h,u){return t(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="ubersicht" tabindex="-1">Übersicht <a class="header-anchor" href="#ubersicht" aria-label="Permalink to &quot;Übersicht&quot;">​</a></h1><p>Die Übersicht ist der Leitstand für das ganze Paket: alle Flights mit ihrem Stand, was noch zu prüfen ist, wer was darf, und die Unterlagen zum Herunterladen.</p><p><img src="'+a+'" alt="Bereich Übersicht mit Prüfungen und Freigaben eines Flights" loading="lazy"></p><h2 id="links-phase-und-paket" tabindex="-1">Links: Phase und Paket <a class="header-anchor" href="#links-phase-und-paket" aria-label="Permalink to &quot;Links: Phase und Paket&quot;">​</a></h2><p><strong>Phase</strong> – nur beim gemeinsamen Planen wichtig:</p><table tabindex="0"><thead><tr><th>Phase</th><th>Bedeutung</th></tr></thead><tbody><tr><td><strong>Entwurf</strong></td><td>Nur der Designer plant. Piloten sehen schon, ändern aber nichts.</td></tr><tr><td><strong>Planung</strong></td><td>Flights arbeiten im Rahmen ihrer Freigaben.</td></tr><tr><td><strong>Eingefroren</strong></td><td>Keine Änderungen mehr durch Flights – z. B. kurz vor dem Briefing.</td></tr></tbody></table><p>Darunter <strong>Paket</strong>: alle spielbaren Flights mit Typ, Aufgabe, Frequenz, Startzeit und Beladung in einer Zeile. Ein rotes <strong>prüfen</strong> zeigt, dass Shardwing etwas gefunden hat; <strong>Hinweise</strong> sind weniger dringend.</p><p>Ganz oben steht der Eintrag <strong>Paket</strong> selbst – dort findest du die Kneeboard-Seiten und darunter die <a href="#kneeboards-fuer-den-jet">Downloads</a>. Darunter öffnet <strong>Wetter</strong> die <a href="#wetter">METARs</a> und <strong>Callsigns &amp; Aufgaben</strong> die <a href="#callsigns-aufgaben">Tabelle der Callsigns</a>, jeweils als eigene Seite. Läufst du als Designer auf einem Server, gibt es dazu den Eintrag <strong>Server</strong> mit Links, Einreichungen und der Mission auf dem Server; die Paket-Seite sieht damit immer gleich aus, mit oder ohne Server.</p><h2 id="kneeboards-fur-den-jet" tabindex="-1">Kneeboards für den Jet <a class="header-anchor" href="#kneeboards-fur-den-jet" aria-label="Permalink to &quot;Kneeboards für den Jet&quot;">​</a></h2><p>Alles, was ein Pilot mitnimmt, an einer Stelle auf der Paket-Seite:</p><ul><li><strong>Alle Flights: Kneeboard-ZIP</strong> und <strong>Alle Flights: ein PDF</strong> für das ganze Paket.</li><li>Je Flight eine Zeile mit <strong>PDF</strong> und <strong>Kneeboard-ZIP</strong> – dieselben Knöpfe wie oben auf der Seite des Flights.</li><li>Wie die Seiten in den Jet kommen: <strong>eingebettet</strong> (Taste K im Cockpit, keine Dateien zu kopieren) oder als <strong>ZIP</strong>, dessen Ordner <code>Kneeboard/&lt;Typ&gt;/</code> du nach <code>Saved Games\\DCS</code> kopierst.</li></ul><p>Die Intel-Zahlen stehen nicht mehr auf der Paket-Seite; die Karte „Intel“ auf der Seite eines Flights bleibt.</p><h2 id="rechts-details-eines-flights" tabindex="-1">Rechts: Details eines Flights <a class="header-anchor" href="#rechts-details-eines-flights" aria-label="Permalink to &quot;Rechts: Details eines Flights&quot;">​</a></h2><p>Klick einen Flight an:</p><h3 id="prufungen" tabindex="-1">Prüfungen <a class="header-anchor" href="#prufungen" aria-label="Permalink to &quot;Prüfungen&quot;">​</a></h3><p>Shardwing schaut automatisch nach typischen Fehlern. Zum Beispiel:</p><ul><li>Gleiche Frequenz wie ein anderer Flight</li><li>Joker/Bingo fehlen auf der Lineup Card</li><li>Keine Cartridge – der Jet startet mit der Missionsroute</li><li>Laser-Code auch bei einem anderen Flight</li><li>Timing: laut Route zu früh oder zu spät am Zielpunkt, lange Wartezeit vor Beginn</li><li>Deconfliction: Annäherung an einen anderen Flight</li><li>Comm Plan: Kanäle in der Cartridge weichen ab</li><li>Threats nur für diesen Flight – Hinweis, Unterlagen per Export zu verteilen, damit andere Flights desselben Typs sie nicht im Kneeboard sehen</li></ul><p>Steht dort <strong>Keine Auffälligkeiten.</strong>, ist der Flight sauber.</p><h3 id="freigaben" tabindex="-1">Freigaben <a class="header-anchor" href="#freigaben" aria-label="Permalink to &quot;Freigaben&quot;">​</a></h3><p>Eine Matrix, was <strong>Lead</strong> und <strong>Wingman</strong> dieses Flights beim gemeinsamen Planen ändern dürfen: Route &amp; Steerpoints, Funk-Presets, CMDS, Lineup Card, eigene Threats, Beladung. Mit <strong>Ansicht als Lead</strong> / <strong>als Wingman</strong> prüfst du das direkt. (<a href="/gemeinsam/rollen">Rollen und Freigaben</a>)</p><h3 id="intel" tabindex="-1">Intel <a class="header-anchor" href="#intel" aria-label="Permalink to &quot;Intel&quot;">​</a></h3><p>Wie viele Bedrohungen der Flight kennt, getrennt nach „für alle“ und „nur für diesen Flight“ – als Anzahl × Typ, ohne Gruppennamen.</p><h3 id="lineup-card-·-kneeboard" tabindex="-1">Lineup Card · Kneeboard <a class="header-anchor" href="#lineup-card-·-kneeboard" aria-label="Permalink to &quot;Lineup Card · Kneeboard&quot;">​</a></h3><p>Die fertigen Seiten des Flights als Vorschau, mit Sprung in den Editor.</p><h3 id="downloads" tabindex="-1">Downloads <a class="header-anchor" href="#downloads" aria-label="Permalink to &quot;Downloads&quot;">​</a></h3><p><strong>PDF</strong> und <strong>Kneeboard-ZIP</strong> für genau diesen Flight. Praktisch, um einem Piloten seine Unterlagen zu schicken.</p><h2 id="mission-abspielen" tabindex="-1">Mission abspielen <a class="header-anchor" href="#mission-abspielen" aria-label="Permalink to &quot;Mission abspielen&quot;">​</a></h2><p>Unten auf der Karte startet <strong>▶ Ablauf</strong> die Mission als Film: Alle Flights bewegen sich nach dem Timing, mit Regler, Tempo und Sprungmarken. Mehr dazu im Bereich <a href="./timing#mission-abspielen">Timing</a>.</p><h2 id="wetter" tabindex="-1">Wetter <a class="header-anchor" href="#wetter" aria-label="Permalink to &quot;Wetter&quot;">​</a></h2><p>Auf der Seite <strong>Wetter</strong> zeigt Shardwing für das Paket das Missionswetter als <strong>METAR</strong> je Flugplatz – Wind am Boden und in der Höhe, QNH, Temperatur, Sicht, Wolken. Mit <strong>+ Flugplatz</strong> fügst du weitere Plätze hinzu, z. B. Diverts.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Der METAR wird aus den Wettereinstellungen der Mission berechnet. Ungewöhnliche Wolken-Presets aus Mods kennt Shardwing nicht immer; dann steht „unbekannt“ daneben.</p></div><h2 id="callsigns-aufgaben" tabindex="-1">Callsigns &amp; Aufgaben <a class="header-anchor" href="#callsigns-aufgaben" aria-label="Permalink to &quot;Callsigns &amp; Aufgaben&quot;">​</a></h2><p>DCS-Callsigns wie „Enfield 1“ sind oft nicht das, was eine Staffel funkt. In dieser Tabelle gibst du jedem Flight:</p><ul><li>einen <strong>eigenen Callsign</strong> mit Nummer (z. B. VIPER 1) – mit <strong>Vorschlägen</strong> passend zur Rolle, schon vergebene ausgeblendet,</li><li>eine <strong>Aufgabe</strong> und Zweitaufgabe (SWEEP, ESCORT, BARCAP, TARCAP, STRIKE, CAS, SEAD, DEAD, AR, AEW …).</li></ul><p>KI-Flights behalten ihren DCS-Callsign (z. B. TEXACO 1) – den sagen sie im Funk; bei ihnen stellst du nur die Aufgabe ein. <strong>Favoriten vergeben</strong> und <strong>Durchnummerieren</strong> helfen bei großen Paketen. Die Namen erscheinen auf allen Unterlagen; Gruppennamen und DCS-Callsigns in der .miz bleiben unverändert.</p><h2 id="briefing-prasentieren" tabindex="-1">Briefing präsentieren <a class="header-anchor" href="#briefing-prasentieren" aria-label="Permalink to &quot;Briefing präsentieren&quot;">​</a></h2><p><strong>▶ Briefing präsentieren</strong> oben in der Seitenleiste zeigt das Briefing als Folien im Vollbild. Gedacht für die Bildschirmfreigabe vor dem Flug: Die Folien entstehen aus der Mission, es gibt nichts vorzubereiten.</p><table tabindex="0"><thead><tr><th>Folie</th><th>Inhalt</th></tr></thead><tbody><tr><td>Titel</td><td>Mission, Karte, Datum, Missionsstart, H-Hour</td></tr><tr><td>Lage und Auftrag</td><td>Die Texte aus dem Briefing der Mission</td></tr><tr><td>Wetter</td><td>METARs der Plätze, Wind, QNH, Wolken</td></tr><tr><td>Kräfte</td><td>Alle Flights mit Aufgabe, Funk und Zeiten, dazu Tanker und AWACS</td></tr><tr><td>Gesamtlage</td><td>Die Karte mit allen Routen und den freigegebenen Bedrohungen</td></tr><tr><td>Zeitachse</td><td>Jeder Flight als Balken mit Push, Zeit am Ziel und Tanker</td></tr><tr><td>Ablauf</td><td>Die Mission spielt auf der Karte ab (siehe <a href="./timing#mission-abspielen">Mission abspielen</a>)</td></tr><tr><td>Funk</td><td>Die Netze des Funkplans, Tanker und AWACS mit Frequenz und TACAN</td></tr><tr><td>Je Flight</td><td>Route auf der Karte, Besetzung, Zeiten, Beladung, Bedrohungen; <strong>Kneeboard zeigen</strong> blättert durch die Seiten</td></tr><tr><td>Fragen</td><td>Die wichtigsten Zeiten zum Schluss</td></tr></tbody></table><p>Folien ohne Inhalt fallen weg, zum Beispiel das Wetter, wenn die Mission keins hat.</p><ul><li><strong>Blättern:</strong> Pfeiltasten oder Leertaste, <strong>Pos1</strong> und <strong>Ende</strong> springen an Anfang und Schluss. Unten lässt sich jede Folie direkt anklicken.</li><li><strong>Karte:</strong> Auf den Kartenfolien ist die Karte nicht eingefroren. Zoomen und Verschieben gehen wie gewohnt.</li><li><strong>Folien:</strong> Der Knopf <strong>Folien</strong> blendet einzelne Folien aus. Die Auswahl merkt sich das Gerät.</li><li><strong>Vollbild:</strong> <strong>F</strong> schaltet das Vollbild um, <strong>Esc</strong> beendet die Präsentation.</li></ul><p>Als Pilot siehst du deine eigene Fassung: die allgemeinen Folien und deinen Flight, mit den Bedrohungen, die für dich freigegeben sind.</p>',41)])])}const m=n(s,[["render",l]]);export{c as __pageData,m as default};
